def make_isotope(t):
    return {"mass_number":t[0],"neutrons":t[1],"mass_da":t[2],"abundance":t[3],"is_stable":t[4],"half_life_s":t[5],"decay_mode":t[6],"spin":t[7]}

def make_element(sym, info):
    return {"symbol":sym,"name":info["name"],"name_en":info["name_en"],"atomic_number":info["Z"],"atomic_mass":info["mass"],"category":info["cat"],"group":info["g"],"period":info["p"],"block":info["b"],"valence_electrons":info["val"],"electronegativity":info["en"],"atomic_radius_pm":info["r"],"covalent_radius_pm":info["cr"],"color":info["color"],"isotopes":[make_isotope(i) for i in info["isotopes"]]}

def main():
    idx_path = os.path.join(OUTPUT_DIR, "_index.json")
    with open(idx_path, "r", encoding="utf-8") as f:
        index = json.load(f)
    elements = index.get("elements", {})
    by_number = index.get("by_number", {})
    categories = index.get("categories", {})
    n = 0
    for sym, info in NEW_ELEMENTS.items():
        data = make_element(sym, info)
        with open(os.path.join(OUTPUT_DIR, f"{sym}.json"), "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        elements[sym] = {"Z": info["Z"], "file": f"{sym}.json", "isotope_count": len(info["isotopes"])}
        by_number[str(info["Z"])] = sym
        cat = info["cat"]
        if cat not in categories: categories[cat] = []
        if sym not in categories[cat]: categories[cat].append(sym)
        n += 1
    index["elements"] = elements
    index["by_number"] = by_number
    index["categories"] = categories
    index["element_count"] = len(elements)
    index["isotope_count"] = sum(e["isotope_count"] for e in elements.values())
    with open(idx_path, "w", encoding="utf-8") as f:
        json.dump(index, f, indent=2, ensure_ascii=False)
    print(f"已新增 {n} 个元素，总计 {len(elements)} 个元素，{index['isotope_count']} 个同位素")

if __name__ == "__main__":
    main()